                    "sql": "Create Or Replace table FUAARK_DB.MAPLEMONK.FUAARK_DB_unicommerce_fact_items as Select null as Customer_ID ,\"Channel Name\" as MARKETPLACE ,\"Channel Name\" as SOURCE ,replace(\"Sale Order Code\",\'`\',\'\') as ORDER_ID ,\"Display Order Code\" as REFERENCE_CODE ,\"Notification Mobile\" as PHONE ,null as NAME ,\"Notification Email\" as EMAIL ,try_cast(UPDATED as timestamp) as SHIPPING_LAST_UPDATE_DATE ,\"Item SKU Code\" as SKU ,\"Seller SKU Code\" as MARKETPLACE_SKU ,\"Channel Product Id\" as PRODUCT_ID ,\"SKU Name\" as PRODUCT_NAME ,\'INR\' as CURRENCY ,coalesce(\"Billing Address City\",\"Shipping Address City\") CITY ,coalesce(\"Billing Address State\",\"Shipping Address State\") as STATE ,\"Sale Order Status\" as ORDER_STATUS ,try_cast(\"Order Date as dd/mm/yyyy hh:MM:ss\" as timestamp) ORDER_DATE ,try_cast(\"Shipping Charges\" as float) as SHIPPING_PRICE ,1 as SUBORDER_QUANTITY ,try_cast(DISCOUNT as float) as discount ,try_cast(igst as float) + try_cast(sgst as float) TAX ,try_cast(\"Selling Price\" as float) as SELLING_PRICE ,\"Shipping Package Code\" as SHIPPINGPACKAGECODE ,\"Shipping Courier Status\" as SHIPPINGPACKAGESTATUS ,\"Sale Order Item Code\" SALEORDERITEMCODE ,\"Sale Order Item Code\" as SALES_ORDER_ITEM_ID ,\"Tracking Number\" AWB ,FACILITY as WAREHOUSE_NAME ,case when try_cast(\"Prepaid Amount\" as int) > 0 then \'PREPAID\' else \'COD\' end as PAYMENT_MODE ,case when try_cast(\"Prepaid Amount\" as int) > 0 then \'PREPAID\' else \'COD\' end as PAYMENT_METHOD ,\"Shipping provider\" as COURIER ,\"Sale Order Item Status\" as SHIPPING_STATUS ,1 as SHIPPEDQUANTITY ,try_cast(\"Dispatch Date\" as timestamp) as DISPATCH_DATE ,try_cast(\"Delivery Time\" as timestamp) as DELIVERED_DATE ,case when try_cast(\"Return Date\" as timestamp) is not null then 1 else 0 end RETURN_FLAG ,case when try_cast(\"Return Date\" as timestamp) is not null then 1 else 0 end RETURN_QUANTITY ,case when lower(\"Sale Order Status\") like \'%cancel%\' then 1 else 0 end as CANCELLED_QUANTITY ,null as NEW_CUSTOMER_FLAG ,null as ACQUISITION_PRODUCT ,null as DAYS_IN_SHIPMENT ,null as ACQUISITION_DATE ,coalesce(p.SKUCODE,pid.SKUCODE,\"Item SKU Code\") AS SKU_CODE ,coalesce(p.name,pid.name,\"SKU Name\") as PRODUCT_NAME_Final ,Upper(coalesce(p.CATEGORY,pid.CATEGORY)) AS Product_Category ,Upper(coalesce(p.SUB_CATEGORY,pid.SUB_CATEGORY)) AS Product_Sub_Category ,upper(coalesce(p.gender,pid.gender)) GENDER ,upper(coalesce(p.mrp,pid.mrp,try_cast(fi.mrp as float))) mrp ,try_cast(\"Return Date\" as timestamp) as return_date from fuaark_db.maplemonk.unicommerce_get_sale_orders fi left join (select * from (select marketplace_sku, skucode, name, category, sub_category, gender , mrp , row_number() over (partition by upper(marketplace_sku) order by length(ifnull(sub_category,\'\')) desc ) rw from FUAARK_DB.MAPLEMONK.FINAL_SKU_MASTER) where rw = 1 ) p on lower(fi.\"Item SKU Code\") = lower(p.marketplace_sku) left join (select * from (select marketplace_sku, skucode, name, category, sub_category, gender , mrp , row_number() over (partition by upper(marketplace_sku) order by length(ifnull(sub_category,\'\')) desc) rw from FUAARK_DB.MAPLEMONK.FINAL_SKU_MASTER) where rw = 1 ) pid on lower(fi.\"Seller SKU Code\") = lower(pid.marketplace_sku) ; Create Or Replace table FUAARK_DB.MAPLEMONK.FUAARK_DB_UNICOMMERCE_RETURNS_INTERMEDIATE as Select \"Channel Name\" as MARKETPLACE ,\"Channel Name\" as SOURCE ,replace(\"Sale Order Code\",\'`\',\'\') as ORDER_ID ,\"Display Order Code\" as REFERENCE_CODE ,\"Notification Mobile\" as PHONE ,null as NAME ,\"Notification Email\" as EMAIL ,try_cast(\"Order Date as dd/mm/yyyy hh:MM:ss\" as timestamp) ORDER_DATE ,\"Display Order Code\" as RETURN_DISPLAYCODE ,\"Sale Order Status\" as RETURN_STATUS ,try_cast(\"Return Date\" as timestamp) INVENTORY_RECEIVED_DATE ,try_cast(\"Return Date\" as timestamp) as RETURN_COMPLETE_DATE ,\"Display Order Code\" as RETURN_INVOICE_DISPLAY_CODE ,\"Shipping provider\" as RETURN_COURIER ,\"Shipping Courier Status\" as RETURN_PROVIDER_SHIPPING_STATUS ,\"Tracking Number\" as RETURN_TRACKING_NUMBER ,null as RETURN_TYPE ,\"Sale Order Item Code\" as SALEORDERITEMCODE ,\"Item SKU Code\" as ITEMSKU ,\"SKU Name\" as ITEM_NAME ,null as INVENTORY_TYPE from fuaark_db.maplemonk.unicommerce_get_sale_orders where try_cast(\"Return Date\" as timestamp) is not null;",
                    "transaction": true
                }
            ) }}
